item.aggregated_output:
        _leaf_json(state_command)
    return parser


def _strict_object(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("duplicate key")
        result[key] = value
    return result


def _reject_constant(_value: str) -> None:
    raise ValueError("non-finite number")


def _input_error(code: str, message: str) -> KokoroError:
    return KokoroError(code, message)


def _input_identity(path_stat: os.stat_result) -> _PathIdentity:
    return _PathIdentity(
        device=path_stat.st_dev,
        inode=path_stat.st_ino,
        size=path_stat.st_size,
        modified_ns=path_stat.st_mtime_ns,
        file_type=stat.S_IFMT(path_stat.st_mode),
        links=path_stat.st_nlink,
    )


def _read_json(path: Path, *, max_bytes: int = JSON_INPUT_MAX_BYTES) -> Any:
    try:
        path_stat = path.lstat()
    except FileNotFoundError as error:
        raise _input_error("INPUT_NOT_FOUND", "Input file was not found.") from error
    except OSError as error:
        raise _input_error(
            "INPUT_READ_FAILED",
            "Input file could not be read.",
        ) from error
    reparse = getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0)
    attributes = getattr(path_stat, "st_file_attributes", 0)
    is_junction = getattr(path, "is_junction", None)
    try:
        junction = bool(is_junction is not None and is_junction())
    except OSError as error:
        raise _input_error(
            "INPUT_READ_FAILED",
            "Input file could not be read.",
        ) from error
    if (
        not stat.S_ISREG(path_stat.st_mode)
        or stat.S_ISLNK(path_stat.st_mode)
        or junction
        or bool(reparse and attributes & reparse)
        or path_stat.st_nlink != 1
    ):
        raise _input_error("INPUT_PATH_UNSAFE", "Input file path is unsafe.")
    if path_stat.st_size > max_bytes:
        raise _input_error("INPUT_TOO_LARGE", "Input file exceeds the size limit.")
    initial_identity = _input_identity(path_stat)
    descriptor: int | None = None
    try:
        flags = os.O_RDONLY | getattr(os, "O_BINARY", 0)
        flags |= getattr(os, "O_NOFOLLOW", 0)
        descriptor = os.open(path, flags)
        with os.fdopen(descriptor, "rb") as handle:
            descriptor = None
            opened_identity = _input_identity(os.fstat(handle.fileno()))
            if opened_identity != initial_identity:
                raise _input_error(
                    "INPUT_PATH_UNSAFE",
                    "Input file path is unsafe.",
                )
            contents = handle.read(max_bytes + 1)
            handle.seek(0)
            repeated = handle.read(max_bytes + 1)
            final_open_identity = _input_identity(os.fstat(handle.fileno()))
    except FileNotFoundError as error:
        raise _input_error("INPUT_NOT_FOUND", "Input file was not found.") from error
    except KokoroError:
        raise
    except OSError as error:
        raise _input_error(
            "INPUT_READ_FAILED",
            "Input file could not be read.",
        ) from error
    finally:
        if descriptor is not None:
            try:
                os.close(descriptor)
            except OSError:
                pass
    if len(contents) > max_bytes:
        raise _input_error("INPUT_TOO_LARGE", "Input file exceeds the size limit.")
    if contents != repeated or final_open_identity != initial_identity:
        raise _input_error("INPUT_PATH_UNSAFE", "Input file path is unsafe.")
    try:
        final_stat = path.lstat()
    except OSError as error:
        raise _input_error("INPUT_PATH_UNSAFE", "Input file path is unsafe.") from error
    if _input_identity(final_stat) != initial_identity:
        raise _input_error("INPUT_PATH_UNSAFE", "Input file path is unsafe.")
    try:
        value = json.loads(
            contents.decode("utf-8"),
            object_pairs_hook=_strict_object,
            parse_constant=_reject_constant,
        )
    except (
        UnicodeDecodeError,
        json.JSONDecodeError,
        RecursionError,
        ValueError,
    ) as error:
        raise _input_error(
            "INPUT_INVALID_JSON",
            "Input file contains invalid JSON.",
        ) from error
    if find_json_incompatibility(value) is not None:
        raise _input_error("INPUT_INVALID_JSON", "Input file contains invalid JSON.")
    return value


def _output_unsafe() -> KokoroError:
    return KokoroError("REPORT_OUTPUT_PATH_UNSAFE", "Report output path is unsafe.")



---LOADER---

def load_yaml(path: Path) -> dict[str, Any]:
    try:
        contents = path.read_bytes()
    except OSError as error:
        raise _invalid_pack_data(
            "YAML file could not be read.", "read_failed"
        ) from error

    return parse_yaml_bytes(contents)


def parse_yaml_bytes(contents: bytes) -> dict[str, Any]:
    """Parse UTF-8 YAML bytes with the pack loader's data-only rules."""
    try:
        text = contents.decode("utf-8")
    except UnicodeError as error:
        raise _invalid_pack_data(
            "YAML file could not be read.", "read_failed"
        ) from error

    loader: _UniqueKeySafeLoader | None = None
    try:
        _reject_alias_events(text)
        loader = _UniqueKeySafeLoader(text)
        document = loader.get_single_data()
    # SafeLoader constructors can raise ordinary Python exceptions for hostile
    # implicit scalars (for example invalid timestamps or guarded huge ints).
    # Keep every data-originated parser failure inside the sanitized boundary.
    except Exception as error:
        raise _invalid_pack_data("YAML document is invalid.", "invalid_yaml") from error
    finally:
        if loader is not None:
            loader.dispose()

    if not isinstance(document, dict):
        raise _invalid_pack_data(
            "YAML document must contain a mapping.", "root_not_mapping"
        )
    return cast(dict[str, Any], document)


def _reject_alias_events(contents: str) -> None:
    events = yaml.parse(contents, Loader=yaml.SafeLoader)
    try:
        for event in events:
            if isinstance(event, yaml.events.AliasEvent):
                raise ConstructorError(
                    None, None, "YAML aliases are disabled", event.start_mark
                )
    finally:
        events.close()


def load_source_pack(root: Path, schemas: SchemaRegistry) -> dict[str, Any]:
    scanned_files = frozenset(scan_pack(root, PackLimits()))
    manifest_path = resolve_pack_file(root, "character.yaml")
    if manifest_path not in scanned_files:
        raise _invalid_pack_data(
            "Character pack reference was not found.", "unscanned_reference"
        )
    manifest = load_yaml(manifest_path)
    references = _validated_manifest_references(manifest)
    resolved_references = _resolve_reference_paths(
        root, references, scanned_files, manifest_path
    )
    source = _assemble_source_pack(
        manifest,
        resolved_references,
        load_yaml,
    )

